import java.sql.*;

public class DB {

    private static Connection conn;

    public static void connect() throws SQLException {
        conn = DriverManager.getConnection("jdbc:mysql://localhost:3306/mydb");
    }

    public static ResultSet executeQuery(String query) throws SQLException {
        Statement stmt = conn.createStatement();
        return stmt.executeQuery(query);
    }
}

public class Police {
    public void search(String lastName) throws SQLException {
        ResultSet rs = DB.executeQuery("SELECT * FROM police WHERE last_name LIKE '%" + lastName + "%'");
        processResults(rs);
    }

    private void processResults(ResultSet rs) throws SQLException {
        StringBuilder sb = new StringBuilder("<table>\n");
        while (rs.next()) {
            String badge = rs.getString("badge");
            String firstName = rs.getString("first_name");
            String lastName = rs.getString("last_name");
            sb.append("<tr><td>" + badge + "</td><td>" + firstName + " " + lastName + "</td></tr>\n");
        }
        sb.append("</table>\n");
        System.out.println(sb.toString());
    }
}

public class Main {
    public static void main(String[] args) throws SQLException {
        Police police = new Police();
        police.connect();
        police.search("SMITH");
    }
}

public class Animal {

    private String nombre;

    private static String especie = "león";

    public Animal(String nombre) {
        this.nombre = nombre;
    }

    public String getNombre() {
        return nombre;
    }

    public static void setEspecie(String e) {
        especie = e;
    }

    public static String getEspecie() {
        return especie;
    }
}

public class StaticVsInstance {
    public static void main(String[] args) {
        Animal a = new Animal("Simba");
        Animal b = new Animal("Mufasa");

        System.out.println(a.getNombre());
        System.out.println(Animal.getEspecie());

        Animal.setEspecie("tigre");

        System.out.println(b.getNombre());
        System.out.println(Animal.getEspecie());
    }
}

