import java.io.*;
import java.net.*;

@SuppressWarnings("unchecked")
public class Serialize util {

    public static EmailMessage deserializeMsg(byte[] serializedMsg)
    {
        FileInputStream fileIn = new FileInputStream(serializedMsg);
        ObjectInputStream in = new ObjectInputStream(fileIn);
        EmailMessage msg = (EmailMessage) in.readObject();
        in.close();
        fileIn.close();
        return msg;
    }

    public static byte[] serializeMsg(EmailMessage msg)
    {
        ArrayList<Path> attachment = msg.getAttachment();
        for(Path path : attachment)
        {
            Path realPath = path.toRealPath();
        }
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        ObjectOutputStream oos = new ObjectOutputStream(baos);
        oos.writeObject(msg);
        oos.close();

        return baos.toByteArray();

    }
}

