import matplotlib.pyplot as plt
import numpy as np

def abc(a,b,c):
    delta = b**2 - 4*a*c
    if delta > 0:
        x1 = (-b + np.sqrt(delta)) / (2*a)
        x2 = (-b - np.sqrt(delta)) / (2*a)
        return np.array([x1, x2])
    elif delta == 0:
        x = -b / (2*a)
        return np.array([x])
    else:
        return np.array([])

def plot_abc(a,b,c):
    roots = abc(a,b,c)
    if len(roots) == 0:
        print("No real roots")
    elif len(roots) == 1:
        print("One real root: ", roots[0])
        plt.plot(roots[0],0,'o')
        plt.text(roots[0],0.05,'{:3.2f}'.format(roots[0]))
    else:
        print("Two real roots: ", roots)
        plt.plot(roots[0],0,'o')
        plt.plot(roots[1],0,'o')
        plt.text(roots[0]-0.2,0.05,'{:3.2f}'.format(roots[0]))
        plt.text(roots[1],0.05,'{:3.2f}'.format(roots[1]))
    x = np.linspace(-10,10,400)
    plt.plot(x, a*x**2 + b*x + c)
    plt.grid(True)
    plt.xlim([-10,10])
    plt.ylim([-10,10])
    plt.show()

plot_abc(1,-2,1)

import React from "react";
import { render } from "@testing-library/react";
import App from "../App";

test("renders welcome message", () => {
  render(<App />);
  const linkElement = screen.getByText(/Welcome to React/i);
  expect(linkElement).toBeInTheDocument();
});

test("renders about message", () => {
  render(<App />);
  const linkElement = screen.getByText(/About this tutorial/i);
  expect(linkElement).toBeInTheDocument();
});

test("renders footer", () => {
  render(<App />);
  const linkElement = screen.getByText(/Footer/i);
  expect(linkElement).toBeInTheDocument();
});
